void StudioWindow::followSelectedElement(){
  if(currentElement().isEmpty()||bridge.busy())return;
  // Commit the focused inspector field before following its current references.
  if(auto focused=QApplication::focusWidget())focused->clearFocus();
  if(!waitForPendingEdits())return;
  showAuthoringWorkspace();emit followAuthoringItem("screenElement:"+screenId+"/"+selection);
}
